usage: fit_model.py [-h] [--template TEMPLATE] [--fix FIX] [--out OUT]
                    [--files FILES] [--maxfev MAXFEV] [--eval]
                    [cand]

positional arguments:
  cand

options:
  -h, --help           show this help message and exit
  --template TEMPLATE
  --fix FIX
  --out OUT
  --files FILES
  --maxfev MAXFEV
  --eval

{
 "params": {
  "XL": 0.3,
  "Re": 0.02,
  "mp": 0.03,
  "mq": 0.05,
  "kpv": 0.05,
  "kiv": 5.0,
  "kff": 0.0,
  "TPf": 0.02,
  "TQf": 0.02,
  "TVf": 0.02,
  "w0": 376.99111843077515
 },
 "defs": {
  "Vcmd": "Vset + mq*(Q0 - Qm)",
  "Ei": "xv + kpv*(Vcmd - Vm) + kff*(Vset - V0)",
  "dl": "delta - theta",
  "Pe": "V*(Re*(Ei*cos(dl) - V) + XL*Ei*sin(dl))/(Re**2 + XL**2)",
  "Qe": "V*(XL*(Ei*cos(dl) - V) - Re*Ei*sin(dl))/(Re**2 + XL**2)"
 },
 "states": {
  "delta": {
   "rhs": "w0*mp*(P0 - Pm)",
   "init": "theta0 + atan2((XL*P0 - Re*Q0)/V0, V0 + (Re*P0 + XL*Q0)/V0)"
  },
  "xv": {
   "rhs": "kiv*(Vcmd - Vm)",
   "init": "sqrt((V0 + (Re*P0 + XL*Q0)/V0)**2 + ((XL*P0 - Re*Q0)/V0)**2)"
  },
  "Pm": {
   "rhs": "(Pe - Pm)/TPf",
   "init": "P0"
  },
  "Qm": {
   "rhs": "(Qe - Qm)/TQf",
   "init": "Q0"
  },
  "Vm": {
   "rhs": "(V - Vm)/TVf",
   "init": "V0"
  }
 },
 "outputs": {
  "P": "Pe",
  "Q": "Qe"
 }
}
